import{_ as r,o as d,c as e,a2 as a}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Crusader Kings III 게임 메커니즘 레퍼런스","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Ref-Crusader-Kings-3.md","filePath":"rules/Ref-Crusader-Kings-3.md"}'),o={name:"rules/Ref-Crusader-Kings-3.md"};function i(n,t,l,s,h,c){return d(),e("div",null,[...t[0]||(t[0]=[a(`<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p></div><blockquote><p>출처 인계: <a href="https://github.com/islee23520/seoul-kenshi/blob/docs/reference-context-sync-st_01a079f1/.omo/research/README.md" target="_blank" rel="noreferrer">공유 조사 색인</a>. 로컬 sources.json·원문 패킷 언급은 조사 당시 기록이며 이 전달에 원시 자료가 포함된다는 뜻이 아니다. 누락된 ID는 미확인으로 남긴다. 자동 생성 문서입니다 — 원본은 저장소 내부 조사 문서(<code>crusader-kings-3.md</code>)에서 파생했으며 금지 용어는 위키 공개 기준에 맞게 치환했다.</p></blockquote><h1 id="crusader-kings-iii-게임-메커니즘-레퍼런스" tabindex="-1">Crusader Kings III 게임 메커니즘 레퍼런스 <a class="header-anchor" href="#crusader-kings-iii-게임-메커니즘-레퍼런스" aria-label="Permalink to &quot;Crusader Kings III 게임 메커니즘 레퍼런스&quot;">​</a></h1><ul><li>작성일: 2026-09-06. 작업 ID: <code>st_01a078b9</code>.</li><li>대상: PC판의 왕조 중심 대전략 게임. 봉건·씨족·부족의 기본 통치 구조를 중심으로 설명하고, Royal Court의 문화 분화·혼합과 Fate of Iberia의 이베리아 투쟁은 확장 규칙으로 구별한다.</li><li>범위: 게임의 작동 원리를 읽는 10개 장의 메커니즘 문서다. 모든 패치·DLC의 이벤트 ID, 건물 단계별 가격, 지역별 병종과 신앙 목록을 망라한 데이터 덤프는 아니다. 2026년 최신 빌드의 수치표로 사용해서는 안 된다.</li><li>조사 제한: 지정된 로컬 보고서만 선행 열람하고 위키 API 5개 페이지를 요청했다. <strong>5건 모두 JSON 대신 브라우저 검증 HTML을 반환하여 원문 확보에 실패했다.</strong> 추가 검색·우회 조회·게임 실행은 하지 않았다. 읽지 못한 위키를 확인된 규칙의 근거로 둔갑시키지 않는다.</li></ul><h3 id="근거-표기-읽는-법" tabindex="-1">근거 표기 읽는 법 <a class="header-anchor" href="#근거-표기-읽는-법" aria-label="Permalink to &quot;근거 표기 읽는 법&quot;">​</a></h3><ul><li><strong>[문서]</strong>: 읽은 로컬 보고서에 명시된 사실. 원출처 S-ID를 함께 적되 이번 작업에서 원출처까지 다시 읽었다는 뜻은 아니다.</li><li><strong>[추론]</strong>: 명시한 메커니즘에서 도출한 전략적 의미·설명용 계산. 게임이 직접 공표한 규칙과 구별한다.</li><li><strong>[미확인]</strong>: 알려진 기본 게임 규칙에 관한 사전 지식이지만, 이번 조사에서 원문·실행으로 대조하지 못했다. 정확한 수치, 현행 패치 적용 여부, DLC 조건은 검증 대기다. 소제목에 이 표기가 있으면 그 아래 표와 목록 전체에 적용된다.</li><li><strong>인용의 범위</strong>: <code>[S-CK3-M02; 원문 미확보]</code> 같은 표기는 관련 위키의 조회 실패 기록과 후속 확인 위치이지, 앞 문장이 그 원문으로 입증되었다는 뜻이 아니다. S19–S33은 선행 로컬 보고서의 원출처 번호를 계승한다.</li><li><strong>중요한 버전 경계</strong>: 출시 이후 계책, 씨족 계약, 전투 우위, 활동·여행, 질병, 정부와 문화가 개편되었다. 서로 다른 시기의 수치를 하나의 &#39;현행 공식&#39;으로 합치지 않는다.</li></ul><h2 id="_1-개요" tabindex="-1">1. 개요 <a class="header-anchor" href="#_1-개요" aria-label="Permalink to &quot;1. 개요&quot;">​</a></h2><h3 id="_1-1-플레이-단위와-목표" tabindex="-1">1.1 플레이 단위와 목표 <a class="header-anchor" href="#_1-1-플레이-단위와-목표" aria-label="Permalink to &quot;1.1 플레이 단위와 목표&quot;">​</a></h3><p><strong>[문서]</strong> CK3의 기본 시점은 영구적인 국가 객체가 아니라 통치하는 <strong>인물과 그 왕조</strong>다. 인물창에서 특성·기량·건강·가족·후계자·관계·궁정·봉신을 연결해 보고, 지도로 영토와 통치자를 선택한다. 개인의 건강은 전술 전투 HP가 아니라 생존·사망 위험과 관계된 속성이다.[S-CK3-M01][S19][S21][S31]</p><p><strong>[미확인]</strong> 기본 역사 시작일의 대표는 867년과 1066년이며, 후속 확장에는 1178년 등 다른 시작일이 추가되었다. 전통적 기본 종료 연도는 1453년이다. 플레이어는 일시정지 가능한 실시간 달력 위에서 결혼·교육·내정·계책·전쟁을 병행한다. 규칙과 플레이 가능 정부에 따라 종료 조건은 달라진다. 전통적 지주 플레이에서는 계승 가능한 같은 왕조의 후계자를 잃거나 플레이 가능한 영지를 잃으면 게임 오버가 될 수 있지만, 무토지 모험가 등 확장 플레이에는 그대로 적용하면 안 된다.</p><p><strong>[추론]</strong> 따라서 핵심 성공 척도는 지도 색칠만이 아니다. &#39;사망 후에도 지배 기반이 남는가&#39;, &#39;가문이 여러 통치자를 배출하는가&#39;, &#39;신앙·문화·가계 계획을 실현했는가&#39;가 병렬 목표다. 현재 군주의 승리가 다음 군주의 분열을 만들 수 있다.</p><h3 id="_1-2-세-겹의-상태-미확인" tabindex="-1">1.2 세 겹의 상태 [미확인] <a class="header-anchor" href="#_1-2-세-겹의-상태-미확인" aria-label="Permalink to &quot;1.2 세 겹의 상태 [미확인]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>층</th><th>소유하는 주요 상태</th><th>전환 시 일어나는 일</th></tr></thead><tbody><tr><td>인물</td><td>나이, 성격, 기량, 생활방식 특전, 건강, 스트레스, 개인 관계, 명예·신앙</td><td>사망하면 그 인물의 선택 능력과 관계망이 종료·재편된다. 개인 명예와 신앙을 왕조 공용 잔고로 취급하지 않는다.</td></tr><tr><td>작위·영지</td><td>작위 법률, 영주, 봉신 관계, 건물, 개발도, 통제력</td><td>계승·전쟁·수여·박탈로 보유자가 바뀌어도 영지의 물적 상태는 대체로 남는다.</td></tr><tr><td>집안·왕조</td><td>친족 계통, 집안 수장·왕조 수장, 왕조 명성, 유산</td><td>플레이 인물이 바뀌어도 장기적 투자와 혈통을 이어 간다.</td></tr></tbody></table><h2 id="_2-코어루프" tabindex="-1">2. 코어루프 <a class="header-anchor" href="#_2-코어루프" aria-label="Permalink to &quot;2. 코어루프&quot;">​</a></h2><h3 id="_2-1-일시정지에서-다음-위기까지" tabindex="-1">2.1 일시정지에서 다음 위기까지 <a class="header-anchor" href="#_2-1-일시정지에서-다음-위기까지" aria-label="Permalink to &quot;2.1 일시정지에서 다음 위기까지&quot;">​</a></h3><p><strong>[문서]</strong> 인물 상태, 상단 중요 경고와 현안 묶음, 자문회 과업, 지도상의 대상 선택이 반복 판단의 입구다. 이벤트는 관련 인물과 선택을 연결하며, 선택에 성격과 맞지 않는 스트레스 부담이 붙을 수 있다.[S19][S27][S29][S30]</p><p><strong>[추론]</strong> 한 바퀴는 다음과 같다.</p><ol><li><strong>진단</strong>: 후계자, 직할 한도, 수입·군비, 봉신 불만, 동맹·전쟁, 스트레스·건강을 확인한다.</li><li><strong>목표 선정</strong>: 상속 안정, 공작령 통합, 특정 결혼, 문화 혁신, 신앙 개혁 등 가까운 목표를 고른다.</li><li><strong>인물 배치</strong>: 배우자·피후견인·자문위원·지휘관·계책 협력자에 적합한 사람을 배치한다.</li><li><strong>행동 확정</strong>: 건설, 혼인, 선물, 계책, 명분 확보, 선전포고에 자원·시간·정치적 위험을 투입한다.</li><li><strong>시간 진행</strong>: 월 수입과 성장, 임신·출생·죽음, 사건, 과업·계책, 군대 이동이 겹쳐 진행된다.</li><li><strong>결과 수습</strong>: 포로 몸값, 새 봉신, 점령지 통제, 부채, 스트레스, 관계 악화에 대응한다.</li><li><strong>세대 전달</strong>: 사망과 계승으로 작위·영토를 재배분하고 새로운 인물로 다시 진단한다.</li></ol><h3 id="_2-2-행동은-시간·자원·사람을-동시에-점유한다-미확인" tabindex="-1">2.2 행동은 시간·자원·사람을 동시에 점유한다 [미확인] <a class="header-anchor" href="#_2-2-행동은-시간·자원·사람을-동시에-점유한다-미확인" aria-label="Permalink to &quot;2.2 행동은 시간·자원·사람을 동시에 점유한다 [미확인]&quot;">​</a></h3><ul><li>자문위원 한 명은 특정 과업에 집중한다. 관리관을 개발도 성장에 두면 그 기간 다른 관리 과업을 쓰지 못한다.</li><li>개인 계책과 적대 계책에는 동시 수행 제한이 있으며 특전·규칙이 이를 바꾼다. 하나의 관계 개선이 다른 혼인·친교 목표를 지연시킨다.</li><li>군대를 소집하면 평시보다 높은 유지비와 병력 손실 위험을 감수한다. 방어전 승리도 재정상 손실일 수 있다.</li><li>혼인은 외교 동맹뿐 아니라 자녀의 왕조·유전·상속권·궁정 위치까지 묶는 장기 계약이다.</li><li>왕조 명성으로 한 인물을 폐적하면, 같은 자원으로 얻을 수 있었던 영구 유산 구매가 늦어진다.</li></ul><h3 id="_2-3-정보와-확정의-경계" tabindex="-1">2.3 정보와 확정의 경계 <a class="header-anchor" href="#_2-3-정보와-확정의-경계" aria-label="Permalink to &quot;2.3 정보와 확정의 경계&quot;">​</a></h3><p><strong>[문서]</strong> 중첩 툴팁은 용어와 계산 원인을 설명하지만, 모든 이벤트가 모든 결과를 공개하지는 않는다. <code>hidden_effect</code>가 존재하고 <code>ai_chance</code>는 AI의 선택 가중치이지 플레이어 성공률이 아니다. 이미 발생한 결과를 확인하는 단일 선택 이벤트도 있다. 알려진 비용, 조건, 성공·발각 가능성, 숨은 결과를 구별해야 한다.[S25][S28][S29][S31]</p><h2 id="_3-진행구조" tabindex="-1">3. 진행구조 <a class="header-anchor" href="#_3-진행구조" aria-label="Permalink to &quot;3. 진행구조&quot;">​</a></h2><h3 id="_3-1-개인-성장과-시대-성장-미확인" tabindex="-1">3.1 개인 성장과 시대 성장 [미확인] <a class="header-anchor" href="#_3-1-개인-성장과-시대-성장-미확인" aria-label="Permalink to &quot;3.1 개인 성장과 시대 성장 [미확인]&quot;">​</a></h3><ul><li><strong>유년기</strong>: 교육 초점과 후견인을 통해 성년 기량·교육 특성·성격 형성에 영향을 준다. 성격은 원하는 보너스를 무제한 장착하는 장비가 아니다.</li><li><strong>성년기</strong>: 생활방식 경험치를 얻고 특전을 해금하며, 혼인·자녀·정복·활동으로 재산과 명예를 축적한다.</li><li><strong>노년기</strong>: 건강 악화, 상속 분배, 미성년 후계자·섭정, 계승 직후 반란에 대비한다. 오래 산 군주의 관계 자산이 후계자에게 그대로 복사되지는 않는다.</li><li><strong>왕조 성장</strong>: 혼인을 통한 혈통 확장과 독립 통치자의 증가가 가문 명성을 키우고, 유산은 여러 세대의 인물에게 효과를 준다.</li><li><strong>문화 시대</strong>: 부족 시대, 중세 초기, 중세 성기, 중세 후기로 혁신 풀이 확장된다. 달력 조건과 기존 혁신 연구 조건을 모두 고려하므로 금을 냈다고 즉시 장자상속을 획득하지 않는다.[S-CK3-M05; 원문 미확보]</li></ul><h3 id="_3-2-계승의-세-가지-질문-미확인" tabindex="-1">3.2 계승의 세 가지 질문 [미확인] <a class="header-anchor" href="#_3-2-계승의-세-가지-질문-미확인" aria-label="Permalink to &quot;3.2 계승의 세 가지 질문 [미확인]&quot;">​</a></h3><ol><li><strong>누가 자격이 있는가</strong>: 남성 전용·남성 우선·평등·여성 우선·여성 전용 등 성별 법, 종교·정부 조건, 적서·서약·폐적 상태.</li><li><strong>어떻게 나누는가</strong>: 연합 분할·분할·고등 분할·단독 상속 등 영역 계승법.</li><li><strong>특정 작위에 별도 법이 있는가</strong>: 선거 작위는 영역 계승법과 다른 후계자를 뽑을 수 있다. 주작위 승계와 모든 백작령 승계를 동일시하지 않는다.[S-CK3-M02; 원문 미확보]</li></ol><h3 id="_3-3-주요-계승법과-의견-효과-미확인" tabindex="-1">3.3 주요 계승법과 의견 효과 [미확인] <a class="header-anchor" href="#_3-3-주요-계승법과-의견-효과-미확인" aria-label="Permalink to &quot;3.3 주요 계승법과 의견 효과 [미확인]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>법률</th><th>작위 배분</th><th>의견·권력 효과와 위험</th></tr></thead><tbody><tr><td>연합 분할 Confederate Partition</td><td>자격 있는 자녀에게 나누며, 조건을 만족하면 분배용 동급 작위를 새로 생성할 수 있다. 주후계자는 주작위와 수도 기반을 우선한다.</td><td>여러 자녀에게 몫을 주는 대신 새 왕국이 생겨 독립할 위험이 있다. 분할 계열은 단독 상속보다 비주후계 자녀에게 우호적인 구조다.</td></tr><tr><td>분할 Partition</td><td>보유 중인 작위를 나누지만 상속 때문에 새 작위를 생성하지 않는다.</td><td>두 번째 왕국 작위를 보유했다면 여전히 분열할 수 있다. &#39;새 작위를 안 만듦&#39;은 &#39;분열 없음&#39;이 아니다.</td></tr><tr><td>고등 분할 High Partition</td><td>주후계자에게 최소 절반의 작위를 우선 배분하고 나머지를 분할한다.</td><td>주후계자의 세력 유지가 쉬워지지만 다른 자녀 몫과 주장을 제거하지 않는다.</td></tr><tr><td>장자상속 Primogeniture</td><td>자격 있는 가장 나이 많은 자녀 계통으로 단독 계승한다.</td><td>영토 보존에 유리하고 제외된 친족은 불만·명분의 근원이 된다. 기술·권위·특수 권한 조건이 있다.</td></tr><tr><td>말자상속 Ultimogeniture</td><td>자격 있는 가장 어린 자녀 계통으로 단독 계승한다.</td><td>긴 재위 가능성과 미성년 계승 위험이 함께 커진다.</td></tr><tr><td>집안 연장자 상속 House Seniority</td><td>집안에서 자격 있는 최고령 인물이 계승한다.</td><td>친자녀 계획보다 집안 전체의 연령 구조가 중요해지고 짧은 재위가 반복될 수 있다.</td></tr><tr><td>선거 Elective</td><td>작위별 유권자가 후보 자격·호감·기량·정치 이해관계에 따라 투표한다. 봉건·스칸디나비아·색슨·태니스트 선거 등의 후보·유권자 규칙이 다르다.</td><td>군주가 원하는 후보를 지지해도 승리가 보장되지 않는다. 봉건 선거의 직속 봉신 의견 <code>+10</code>은 알려진 기본 규칙의 예시지만 이번 원문 대조는 하지 못했다. 적용 작위와 다른 선거법에 일반화하지 않는다.</td></tr></tbody></table><p>분할·장자상속 등 법률 자체의 <strong>정확한 의견 수치와 적용 대상</strong>은 현재 확인하지 못했다. 친족의 상속 불만, 권위 변경의 봉신 불만, 선거법의 법률 보너스, &#39;전임자에 대한 의견&#39;을 하나의 고정 보정으로 합산해서는 안 된다. 법 변경은 필요한 혁신·왕권·봉신 동의·명예 비용을 해당 UI에서 별도로 확인해야 한다.[S-CK3-M02; 원문 미확보]</p><p><strong>[추론: 분할 예시]</strong> 왕국 A·B를 가진 왕에게 동등한 자격의 두 아들이 있고 별도 선거·예외가 없다면, 주후계자가 A를 받고 다른 아들이 B를 받아 동급 독립 왕이 될 수 있다. 반대로 주후계자가 제국을 이어받고 형제가 제국 아래 왕국만 받는다면 형제는 보통 봉신으로 남는다. 정확한 분배는 기존 생전 수여와 작위 계층까지 반영하므로 &#39;자녀 수로 백작령을 단순 나눔&#39;은 실제 알고리즘이 아니다.</p><h3 id="_3-4-계승-준비의-수단과-비용-미확인" tabindex="-1">3.4 계승 준비의 수단과 비용 [미확인] <a class="header-anchor" href="#_3-4-계승-준비의-수단과-비용-미확인" aria-label="Permalink to &quot;3.4 계승 준비의 수단과 비용 [미확인]&quot;">​</a></h3><p>생전 작위 수여, 주작위·수도 관리, 선거 도입·투표 영향력, 적법한 폐적, 종교가 허용하는 수도 서약, 혼인·출산 조절, 상위 작위 생성이 대안이다. 폐적은 왕조 명성·개인 명예와 친족 관계 비용을 수반할 수 있고, 살해는 적대 계책의 실패·발각·친족살해 위험을 가진다. 작위 파괴는 해당 봉신 불만과 명예 비용을 만들며 연합 분할의 재생성을 반드시 막지는 못한다.[S-CK3-M02][S-CK3-M06; 원문 미확보]</p><h2 id="_4-경제" tabindex="-1">4. 경제 <a class="header-anchor" href="#_4-경제" aria-label="Permalink to &quot;4. 경제&quot;">​</a></h2><h3 id="_4-1-서로-교환되지-않는-주요-자원-미확인" tabindex="-1">4.1 서로 교환되지 않는 주요 자원 [미확인] <a class="header-anchor" href="#_4-1-서로-교환되지-않는-주요-자원-미확인" aria-label="Permalink to &quot;4.1 서로 교환되지 않는 주요 자원 [미확인]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>자원</th><th>대표 유입</th><th>대표 지출·용도</th><th>별도 누적 지표</th></tr></thead><tbody><tr><td>금 Gold</td><td>직할 세금, 봉신 납부, 몸값, 약탈, 교계 지원, 사건</td><td>건설, 무장병 모집·유지, 소집군, 용병, 선물·뇌물, 활동, 작위 생성</td><td>부채는 행동 제약과 군사·정치 압박을 만든다.</td></tr><tr><td>명예 Prestige</td><td>작위·지위, 전쟁·활동·사건, 혼인</td><td>일부 전쟁 명분, 법·문화 변경, 부족 병력·건설 등</td><td>위신 단계 Level of Fame는 보유 잔고와 구별한다.</td></tr><tr><td>신앙 Piety</td><td>학습·성직·순례·교리 친화 행동, 전쟁·사건</td><td>성전, 교계 요청, 개종·신앙 창설·개혁 등</td><td>헌신 단계 Level of Devotion는 보유 잔고와 구별한다.</td></tr><tr><td>왕조 명성 Renown</td><td>살아 있는 왕조원, 독립 통치자·혼인 관계의 조건부 기여, 특수 효과</td><td>왕조 유산, 폐적 등 수장 행동</td><td>왕조 장엄도 Level of Splendor와 잔고를 구별한다.</td></tr></tbody></table><p>단순히 자원을 지출했다고 그 자원에 대응하는 명성 단계가 같은 양으로 하락하는 것은 아니다. 행위 자체가 불명예·불신앙으로 판정되는 경우는 별도다. 개인 자원과 왕조 공용 자원을 섞지 않는다.</p><h3 id="_4-2-직할령-개발도-통제력-미확인" tabindex="-1">4.2 직할령, 개발도, 통제력 [미확인] <a class="header-anchor" href="#_4-2-직할령-개발도-통제력-미확인" aria-label="Permalink to &quot;4.2 직할령, 개발도, 통제력 [미확인]&quot;">​</a></h3><ul><li><strong>직할 한도 Domain Limit</strong>: 통치자가 직접 보유할 수 있는 영지의 한도. 관리 기량·작위 등급·배우자 지원·특전·문화 등으로 달라진다. 전통적 기본 규칙의 관리 <code>6</code>당 직할 한도 <code>+1</code>은 버전 대조가 필요한 수치다.</li><li><strong>직할 초과</strong>: 세금·징집병 효율에 불이익이 생긴다. 무한히 직접 보유하는 것보다 충성할 봉신에게 나누는 이유다. 최신 초과 1개당 비율은 미확인이다.</li><li><strong>개발도 Development</strong>: 군사·경제 생산과 문화 혁신의 기반. 알려진 봉건·씨족 기본 효과는 개발도 1당 세금과 징집병 <code>+0.5%</code>지만 정부별 예외와 최신 수치는 미확인이다.</li><li><strong>통제력 Control</strong>: 백작령의 통치 집행 수준으로 보통 <code>0–100</code>. 점령·반란·사건으로 떨어지고 무관장 과업 등으로 회복한다. 알려진 기본 규칙은 100 미만에서 통제력 1 부족당 세금 <code>-1%</code>, 징집병 <code>-0.5%</code>지만 현행 적용·상한·특수 효과는 미확인이다.</li><li><strong>건물</strong>: 금을 선지출하고 건설 시간을 지나 세금·병력·보급·무장병 주둔 효과 등을 얻는다. 지형·영지 유형·문화 혁신·건물 슬롯과 단계가 제약한다. 무장병 주둔 보너스는 출시 당시의 전역 건물 보너스와 혼합하면 안 된다.</li></ul><p><strong>[추론: 경제 판단식]</strong> <code>월 순수입 = 직할 수입 + 봉신 수입 + 기타 정기 수입 - 군비 - 궁정·직책·기타 정기 비용</code>. 이는 항목을 설명하는 회계식이며, 모든 게임 보정의 적용 순서를 재현한 엔진 공식은 아니다. 건설의 단순 회수 기간은 <code>건설비 / 추가 월 순수입</code>이지만 사망·정복·상속에 따른 소유권 변경을 무시하므로 장기 의사결정의 전부가 될 수 없다.</p><h3 id="_4-3-봉신-수입과-정부-미확인" tabindex="-1">4.3 봉신 수입과 정부 [미확인] <a class="header-anchor" href="#_4-3-봉신-수입과-정부-미확인" aria-label="Permalink to &quot;4.3 봉신 수입과 정부 [미확인]&quot;">​</a></h3><ul><li><strong>봉건</strong>: 봉신 계약이 세금과 징집병 의무를 정한다. 높은 의무는 일반적으로 봉신 호감을 낮추며, 구실이나 상응하는 양보 없이 불리하게 바꾸면 폭정 문제를 만들 수 있다. 성벽·군역·자문회 권리 같은 특수 조항도 거래 대상이다.</li><li><strong>씨족</strong>: 초기 규칙에는 군주에 대한 의견이 세금·병력 기여에 직접 중요했다. 후속 규칙에는 세금 관할·징세관·세금 정책이 도입되었다. 두 체계를 같은 현행 계산식으로 제시하지 않는다.</li><li><strong>부족</strong>: 위신 단계가 봉신 기여와 통치 능력에 중요하고 일부 군비·건설에 금 대신 명예를 쓴다. 봉건화는 경제 기반과 군사 비용 구조를 바꾸는 전환이다.</li><li><strong>신정·공화 봉신</strong>: 종교와 정부별 규칙으로 납부한다. 특히 성직자 지지가 사원 수입에 영향을 주는 신앙과 직접 사원을 보유하는 신앙을 구별한다.</li><li><strong>행정제·유목제·무토지</strong>: 확장별 별도 경제·계승 체계가 있으므로 봉건 계약 공식을 그대로 적용하지 않는다. 이 문서에서 각각의 세부 수치는 검증하지 않았다.</li></ul><h3 id="_4-4-비용은-고정표-하나로-끝나지-않는다-미확인" tabindex="-1">4.4 비용은 고정표 하나로 끝나지 않는다 [미확인] <a class="header-anchor" href="#_4-4-비용은-고정표-하나로-끝나지-않는다-미확인" aria-label="Permalink to &quot;4.4 비용은 고정표 하나로 끝나지 않는다 [미확인]&quot;">​</a></h3><p>선물은 대상의 지위·관련 보정에 따라 가격과 의견 효과가 달라진다. 명분 위조의 완료 선택에는 금이 필요할 수 있다. 궁정 직책과 군비는 월 유지비다. 용병은 계약 선불 비용과 계약 기간이 핵심이며, 계책 협력자 매수는 일시 비용이다. 따라서 &#39;계책 한 번 = 금 100&#39;처럼 모든 대상을 같은 가격으로 쓰면 틀린다.</p><h2 id="_5-캐릭터-파티" tabindex="-1">5. 캐릭터/파티 <a class="header-anchor" href="#_5-캐릭터-파티" aria-label="Permalink to &quot;5. 캐릭터/파티&quot;">​</a></h2><h3 id="_5-1-다섯-기량과-별도-무용" tabindex="-1">5.1 다섯 기량과 별도 무용 <a class="header-anchor" href="#_5-1-다섯-기량과-별도-무용" aria-label="Permalink to &quot;5.1 다섯 기량과 별도 무용&quot;">​</a></h3><p><strong>[문서]</strong> CK3는 외교·전투·관리·계책·학습의 다섯 주요 기량과 개인 무용을 구별한다. 특성과 보정이 기량에 영향을 주며, 건강은 사망 위험과 관계한다. 전술 RPG의 고정 파티 대신 가족·궁정·자문회·봉신·군대의 서로 겹치는 인물망이 존재한다.[S21][S27][S31]</p><p>다음 역할·수치의 세부는 **[미확인]**이다.</p><table tabindex="0"><thead><tr><th>기량</th><th>주요 작용</th><th>대표 생활방식 특전 트리</th></tr></thead><tbody><tr><td>외교 Diplomacy</td><td>일반 의견, 외교 제안, 설득·친교, 명예 관련 행동</td><td>외교관 Diplomat / 위엄 August / 가장 Family Hierarch</td></tr><tr><td>전투 Martial</td><td>군 통솔, 지휘관 우위, 군사 과업과 전쟁 관련 선택</td><td>전략가 Strategist / 감독관 Overseer / 용감한 기사 Gallant</td></tr><tr><td>관리 Stewardship</td><td>직할 한도와 세금, 건설·재정 과업</td><td>재물 Avaricious / 건축가 Architect / 행정가 Administrator</td></tr><tr><td>계책 Intrigue</td><td>적대 계책, 방첩, 협박·유혹·공포 관련 선택</td><td>모략가 Schemer / 유혹자 Seducer / 고문가 Torturer</td></tr><tr><td>학습 Learning</td><td>종교·문화 연구, 의술·건강·교육 관련 행동</td><td>온전한 신체 Whole of Body / 학자 Scholar / 신학자 Theologian</td></tr><tr><td>무용 Prowess, 별도</td><td>기사로서 개인 전투력·결투·부상 위험</td><td>다섯 기본 생활방식과 별개의 개인 전투 능력. 지휘관 전투 기량과 혼동하지 않는다.</td></tr></tbody></table><h3 id="_5-2-생활방식-경험치와-특전-미확인" tabindex="-1">5.2 생활방식 경험치와 특전 [미확인] <a class="header-anchor" href="#_5-2-생활방식-경험치와-특전-미확인" aria-label="Permalink to &quot;5.2 생활방식 경험치와 특전 [미확인]&quot;">​</a></h3><p>기본 다섯 생활방식은 각각 세 집중과 세 특전 트리를 제공한다. 선택한 생활방식에서 경험치를 얻고, 특전 점수로 선행 조건을 따라 노드를 해금하면 완성 특성에 도달한다. 교육 특성·천재성·기타 효과가 경험치 획득에 영향을 준다. 알려진 기본 값은 월 경험치 <code>25</code>, 특전 1점당 경험치 <code>1,000</code>, 집중 변경 대기 <code>5년</code>이지만 최신 패치 대조는 하지 못했다.</p><p>특전은 단순 <code>기량 +1</code>뿐 아니라 새로운 행동을 연다. 예를 들어 외교의 친교 계책, 관리의 구실 대가로 금 요구, 계책의 납치, 학습의 신앙 구매 명분 등이 있다. 선지자 Prophet 특전의 신앙 창설·개혁 비용 <code>-50%</code>는 알려진 대표 효과이며 현행 값은 미확인이다. 후속 확장의 추가 생활방식을 포함해 &#39;CK3에는 언제나 딱 다섯 종류만 있다&#39;고 일반화하지 않는다.[S32: 생활방식과 인물 서사의 연결만 문서 근거]</p><h3 id="_5-3-가족-유전-관계-미확인" tabindex="-1">5.3 가족, 유전, 관계 [미확인] <a class="header-anchor" href="#_5-3-가족-유전-관계-미확인" aria-label="Permalink to &quot;5.3 가족, 유전, 관계 [미확인]&quot;">​</a></h3><ul><li>혼인 형태가 자녀의 왕조를 결정한다. 일반적 부계 혼인과 모계 혼인을 구별하고, 동맹만 보고 후계자의 왕조를 놓치지 않아야 한다.</li><li>선천 특성은 유전 확률·강화·열성 전달을 가질 수 있다. 양쪽 부모가 같은 긍정 특성을 가졌다고 모든 경우 완전한 결과가 보장되는 것은 아니다.</li><li>교육 특성, 성격 특성, 선천 특성, 생활방식 완성 특성, 질병·부상·범죄 표식은 별개의 범주다.</li><li>친구·절친·연인·천생연분·경쟁자·숙적은 단순 의견 점수와 다른 관계 상태다. 관계는 사건·스트레스·계책 조건에 관여한다.[S20: 관계 범주와 의견 방향은 문서 근거]</li></ul><h3 id="_5-4-자문회와-인물-배치" tabindex="-1">5.4 자문회와 인물 배치 <a class="header-anchor" href="#_5-4-자문회와-인물-배치" aria-label="Permalink to &quot;5.4 자문회와 인물 배치&quot;">​</a></h3><p><strong>[문서]</strong> 자문회 과업의 효과는 담당자의 기량과 연결되고 임명 제한·요구조건이 존재한다. 후보를 정렬·필터링하여 업무와 인물을 연결한다.[S19][S27]</p><p>아래 기본 업무와 비용은 **[미확인]**이다.</p><table tabindex="0"><thead><tr><th>자리</th><th>기량·기능</th><th>실질 비용·갈등</th></tr></thead><tbody><tr><td>재상 Chancellor</td><td>외교: 대외 관계, 국내 봉신 관계, 작위 관습권 통합 관련 과업</td><td>뛰어난 평민 대신 유력 봉신을 앉힐 정치적 유인이 있다.</td></tr><tr><td>무관장 Marshal</td><td>전투: 통제력 증가, 군대 조직·기사 훈련 등</td><td>반란 지역 안정과 전투력 강화를 동시에 최대로 할 수 없다.</td></tr><tr><td>관리관 Steward</td><td>관리: 세금 징수, 개발도 증가, 문화 촉진</td><td>단기 세금, 장기 성장, 동화 사이의 기회비용.</td></tr><tr><td>첩보장 Spymaster</td><td>계책: 계책 지원·방해, 비밀 탐색</td><td>불충한 고기량 첩보장은 자신을 노리는 계책에 위험한 인물이 된다.</td></tr><tr><td>궁정 사제·주교</td><td>학습: 개종, 종교 관계, 명분 위조 등</td><td>신앙 교리에 따라 직접 임명·해임 가능 여부가 다르고 위조 완료에 금이 들 수 있다.</td></tr><tr><td>배우자</td><td>전반적 보조 또는 특정 기량 지원</td><td>특정 기량 집중의 알려진 기본 전달률은 배우자 해당 기량의 50%, 전반 보조는 각 20%이나 현행·섭정·배우자 자격 예외는 미확인이다.</td></tr></tbody></table><p>유력 봉신의 자문회 자리 요구를 무시하면 알려진 기본 의견 보정 <code>-40</code>이 발생할 수 있다. 이것은 &#39;모든 자문위원을 월급으로 고용한다&#39;는 뜻이 아니다. 자문회 직위와 월급을 받는 궁정 직책을 구별한다. 자격·신앙·봉신 계약에 따라 배치 자유가 제한된다.</p><h3 id="_5-5-왕조-유산-요청된-5개-트리-×-5단계-미확인" tabindex="-1">5.5 왕조 유산: 요청된 5개 트리 × 5단계 [미확인] <a class="header-anchor" href="#_5-5-왕조-유산-요청된-5개-트리-×-5단계-미확인" aria-label="Permalink to &quot;5.5 왕조 유산: 요청된 5개 트리 × 5단계 [미확인]&quot;">​</a></h3><p><strong>먼저 범위 정정:</strong> 기본 왕조 유산은 이 다섯 트리만이 아니다. 아래는 요청 범위에 맞춘 대표 다섯 트리의 25단계이며, <strong>Erudition·Glory도 기본 계열</strong>이고 지역·DLC 유산이 추가된다. 생활방식 특전은 개인에게, 왕조 유산은 해당 왕조에 장기 적용되는 점이 다르다. 구매 주체는 왕조 수장이며 공용 명성을 쓴다. 알려진 기본 구매 비용은 전체 구매 횟수에 따라 <code>250, 750, 1,250, ...</code>처럼 500씩 증가하지만 현행·특수 해금 비용은 미확인이다.[S-CK3-M06; 원문 미확보]</p><p>아래 영어 명칭은 식별용이고 한국어는 의미 번역이다. <strong>25개 모두 이번 원문 대조가 없으며</strong>, 효과는 알려진 기본판 중심이다. 지역·패치의 추가 효과를 생략한 표이므로 최신 완전 효과 목록으로 사용하지 않는다.</p><table tabindex="0"><thead><tr><th>트리</th><th>단계·명칭</th><th>대표 기계적 효과</th></tr></thead><tbody><tr><td>Warfare 전쟁</td><td>1 House of Warriors, 전사의 집안</td><td>무용 <code>+2</code>, 기사 효율 <code>+15%</code>.</td></tr><tr><td>Warfare</td><td>2 Generational Belligerence, 대대로 호전적</td><td>명분 비용 <code>-20%</code>. 모든 전쟁 유지비 감소라는 뜻은 아니다.</td></tr><tr><td>Warfare</td><td>3 Squire Traditions, 종자 전통</td><td>군사 생활방식 경험치 <code>+10%</code>.</td></tr><tr><td>Warfare</td><td>4 Inherited Tactics, 전술 계승</td><td>무장병 상성 대응 효율 <code>+15%</code>.</td></tr><tr><td>Warfare</td><td>5 Private Army, 사병</td><td>무장병 연대 수 한도 <code>+1</code>. 한 연대의 병력 크기 한도와 다르다.</td></tr><tr><td>Law 법</td><td>1 Mostly Fair, 대체로 공정</td><td>사냥·연회 비용 <code>-30%</code>가 알려진 구판 대표 효과. 활동 개편 후 정확한 적용 항목은 미확인.</td></tr><tr><td>Law</td><td>2 Faithful Magistrates, 충실한 행정관</td><td>봉신 대중 의견 <code>+5</code> 계열의 민심 안정 효과. 개인 봉신의 군주 호감과 대중 의견을 구별한다. 정확한 현행 대상 범위 미확인.</td></tr><tr><td>Law</td><td>3 Power and Prosperity, 권력과 번영</td><td>관리 생활방식 경험치 <code>+10%</code>.</td></tr><tr><td>Law</td><td>4 Delegated Authority, 권한 위임</td><td>유력 봉신 의견 <code>+5</code>.</td></tr><tr><td>Law</td><td>5 Home Estates, 가문 영지</td><td>직할 한도 <code>+1</code>.</td></tr><tr><td>Guile 모략</td><td>1 Ominous Reputation, 불길한 평판</td><td>공포 획득 <code>+20%</code>. 현재 공포에 즉시 20을 더하는 효과가 아니다.</td></tr><tr><td>Guile</td><td>2 Long Reach, 뻗치는 손길</td><td>적대 계책 성공 가능성 <code>+10</code> 계열. 계책 개편 전 성공률 보정으로 알려졌으며 현행 수치 단위 미확인.</td></tr><tr><td>Guile</td><td>3 Natural Schemers, 타고난 모략가</td><td>계책 생활방식 경험치 <code>+10%</code>.</td></tr><tr><td>Guile</td><td>4 Venial, 너그러운 해석</td><td>폭정 획득 <code>-20%</code>. 폭정을 무효화하지 않는다.</td></tr><tr><td>Guile</td><td>5 Family Connections, 가문의 연줄</td><td>왕조원 대상 적대 계책 방어·실패 시 상대 정보 확보와 연결된 효과로 알려져 있다. <strong>현재 정확한 발동·보정은 미확인</strong>이므로 고정 -50% 방어 같은 수치를 확정하지 않는다.</td></tr><tr><td>Blood 혈통</td><td>1 Noble Veins, 고귀한 혈관</td><td>좋은 선천 특성의 유전·새 발생 확률 <code>+30%</code> 계열. 확률의 30%p 가산이라고 단정하지 않는다.</td></tr><tr><td>Blood</td><td>2 Convergent Blood, 모이는 혈통</td><td>선천 특성 강화 확률 <code>+30%</code> 계열.</td></tr><tr><td>Blood</td><td>3 Resilient Bloodline, 강인한 혈통</td><td>나쁜 선천 특성의 유전·새 발생 확률 <code>-30%</code> 계열. 근친 위험 전체가 제거되는 것은 아니다.</td></tr><tr><td>Blood</td><td>4 Architected Ancestry, 설계된 혈통</td><td>지정 가능한 선천 특성 중 하나를 선택해 왕조 내 출현을 장려한다. 선택 가능한 특성·확률은 미확인.</td></tr><tr><td>Blood</td><td>5 Octogenarians, 팔순의 사람들</td><td>기대수명 관련 <code>+5년</code> 효과. 모든 인물의 확정 사망일을 5년 연기한다는 뜻은 아니다.</td></tr><tr><td>Kin 친족</td><td>1 Bounteous Loins, 다산</td><td>생식력 <code>+10%</code>.</td></tr><tr><td>Kin</td><td>2 Studious Youth, 학구적인 유년</td><td>더 좋은 교육 결과를 얻을 가능성을 높인다. 최상위 교육 확정은 아니다.</td></tr><tr><td>Kin</td><td>3 Constant Care, 지속적인 돌봄</td><td>질병·출산·회복 관련 왕조 사건의 돌봄 효과. 정확한 건강량·사건 조건은 미확인.</td></tr><tr><td>Kin</td><td>4 Close Bonds, 긴밀한 유대</td><td>왕조원 의견 <code>+10</code>.</td></tr><tr><td>Kin</td><td>5 Graceful Aging, 우아한 노화</td><td>노화로 무용을 잃지 않고 나이가 들며 기량이 개선될 수 있다. 질병·부상·사망 면역은 아니다.</td></tr></tbody></table><p><strong>[추론]</strong> 혈통·친족은 인물 공급의 질과 안정성을, 전쟁·법·모략은 해당 인물을 운용할 때의 효율을 장기 개선한다. 명성 가격이 전체 구매량에 따라 오르면 첫 단계만 분산 구매하는 전략도 이후 마지막 단계 도달을 늦춘다.</p><h2 id="_6-전투" tabindex="-1">6. 전투 <a class="header-anchor" href="#_6-전투" aria-label="Permalink to &quot;6. 전투&quot;">​</a></h2><h3 id="_6-1-군대-구성-미확인" tabindex="-1">6.1 군대 구성 [미확인] <a class="header-anchor" href="#_6-1-군대-구성-미확인" aria-label="Permalink to &quot;6.1 군대 구성 [미확인]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>요소</th><th>역할·대표 기본 수치</th><th>제약·비용</th></tr></thead><tbody><tr><td>징집병 Levies</td><td>기본 피해 <code>10</code>, 강인함 <code>10</code>인 대량 병력으로 알려져 있다.</td><td>소집 시 금 유지비와 보급을 소비하며 강한 무장병의 질을 자동으로 따라가지 못한다.</td></tr><tr><td>무장병 Men-at-Arms</td><td>모집한 연대를 유지·증원한다. 피해·강인함·추격·엄호와 상성이 다르다.</td><td>연대 수·크기 한도, 모집·유지비, 문화·혁신 해금, 주둔 건물·지형이 제약한다.</td></tr><tr><td>기사 Knights / Champions</td><td>개인 무용과 기사 효율에 따라 큰 전투 기여를 한다. 알려진 기본은 무용 1당 피해 <code>100</code>, 강인함 <code>10</code>.</td><td>기사 수 한도와 인재 확보, 부상·전사·포로 위험. 무용 높은 후계자를 출전시키면 계승도 위험해진다.</td></tr><tr><td>지휘관 Commander</td><td>전투 기량, 지휘 특성, 지형·상황으로 우위를 결정한다.</td><td>한 군대의 지휘관 선택이 병종 조합을 대신하지 않는다.</td></tr><tr><td>용병 Mercenaries</td><td>계약한 추가 병력으로 단기간 병력 차이를 메운다.</td><td>선불 금, 계약 만료·연장, 채용 가능 여부.</td></tr><tr><td>성전 기사단 Holy Orders</td><td>신앙 적대 상대와의 전쟁에 종교 병력을 제공한다.</td><td>전쟁 대상·후원자·고용 자격, 신앙 비용, 이미 다른 전쟁에서 고용되었는지 여부.</td></tr></tbody></table><p>이 절의 숫자·상성·공식은 모두 위키 Warfare 원문을 확보하지 못한 상태의 기본 규칙 요약이다.[S-CK3-M03; 원문 미확보]</p><h3 id="_6-2-무장병-유형과-상성-미확인" tabindex="-1">6.2 무장병 유형과 상성 [미확인] <a class="header-anchor" href="#_6-2-무장병-유형과-상성-미확인" aria-label="Permalink to &quot;6.2 무장병 유형과 상성 [미확인]&quot;">​</a></h3><ul><li><strong>경보병·산병 Skirmishers</strong>: 저렴한 편이며 중보병에 대응한다.</li><li><strong>궁병 Archers</strong>: 산병에 대응한다.</li><li><strong>중보병 Heavy Infantry</strong>: 높은 피해·강인함을 가지며 창병에 대응한다.</li><li><strong>창병 Spearmen</strong>: 경기병·중기병에 대응한다.</li><li><strong>경기병 Light Cavalry</strong>: 궁병에 대응하며 높은 추격으로 패주 병력 손실을 키운다.</li><li><strong>중기병 Heavy Cavalry</strong>: 높은 충격력으로 궁병·일부 보병에 대응하나 비싸고 지형 제약을 받는다. 정확한 대응 병종은 개별 연대 툴팁을 확인한다.</li><li><strong>궁기병·낙타·전쟁 코끼리·지역 고유 무장병</strong>: 일반 병종과 다른 대응·지형 보정을 가질 수 있다. 상위 비용의 보편 업그레이드가 아니다.</li><li><strong>공성 병기</strong>: 망고넬·트레뷰셋·사석포 등 혁신 단계에 따라 높은 요새에 대응한다. 야전 주력이 아니다.</li></ul><p>상성은 &#39;유리한 병종이 있으면 무조건 승리&#39;가 아니라 상대 병종의 유효 피해를 낮추는 체계다. 대응 병력의 비율, 효율 보정, 여러 대상 사이의 분배가 중요하다. 알려진 기본 감쇠 상한은 피해 <code>90%</code> 감소이지만 최신 정확한 상성 분배식은 미확인이다.</p><h3 id="_6-3-전투-단계-너비-우위-미확인" tabindex="-1">6.3 전투 단계, 너비, 우위 [미확인] <a class="header-anchor" href="#_6-3-전투-단계-너비-우위-미확인" aria-label="Permalink to &quot;6.3 전투 단계, 너비, 우위 [미확인]&quot;">​</a></h3><p>군대가 같은 전장에 맞물리면 자동으로 교전한다. 플레이어의 직접 개입은 사전 병력 편성·지휘관·진군로·증원·후퇴 판단이지 개별 기사의 격자 이동이 아니다. <strong>간접 전투라는 성격 자체는 선행 문서에서 확인된다.</strong>[S30]</p><ol><li><strong>초기 교전</strong>: 즉시 임의 후퇴할 수 없는 구간이 있다. 크게 열세인 군대는 이 구간에서 전멸할 수 있다.</li><li><strong>본 전투</strong>: 배치 병력이 서로 피해를 주고 손실이 누적된다. 전투 너비가 동시에 싸우는 병력량을 제한하며 지형이 너비를 바꾼다.</li><li><strong>패주·추격</strong>: 진 쪽의 엄호와 이긴 쪽의 추격이 추가 손실을 바꾼다.</li><li><strong>후퇴·회복</strong>: 패배군이 퇴각하고, 안전·보급·보충 조건 아래 병력이 회복된다.</li></ol><p>우위 Advantage는 양측 지휘·지형·도하·상륙·보급·군대 상태·전투 굴림 등의 차이다. 높은 쪽의 피해량을 증폭한다. <strong>구판의 &#39;우위 1당 2%&#39;와 후속 패치에서 쓰인 &#39;1당 10%&#39;를 동일한 현행 규칙으로 합치지 않는다.</strong> 이 조사에서는 최신 계수와 재조정 이력을 확인하지 못했다.</p><h3 id="_6-4-전투-해결-수식-설명-가능한-범위와-검증-경계" tabindex="-1">6.4 전투 해결 수식: 설명 가능한 범위와 검증 경계 <a class="header-anchor" href="#_6-4-전투-해결-수식-설명-가능한-범위와-검증-경계" aria-label="Permalink to &quot;6.4 전투 해결 수식: 설명 가능한 범위와 검증 경계&quot;">​</a></h3><p><strong>[미확인: 기본 구조]</strong> 병종 <code>i</code>의 실제 교전 병력을 <code>N_i</code>, 기본 피해를 <code>d_i</code>, 피해 보정을 <code>B_i</code>, 상성 감쇠율을 <code>C_i</code>라 두면 군의 공격 기여를 다음처럼 분해해 이해할 수 있다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D_side = Σ_i [N_i × d_i × (1 + B_i) × (1 - C_i)] + D_knights</span></span>
<span class="line"><span>D_knights = Σ_k [무용_k × 100 × 기사효율_k]</span></span>
<span class="line"><span>A = max(0, 내 우위 - 상대 우위)</span></span>
<span class="line"><span>우위 반영 피해 = D_side × (1 + k_adv × A)</span></span>
<span class="line"><span>개념상 일일 손실 ≈ 우위 반영 피해 × k_day / 상대 유효 강인함</span></span></code></pre></div><ul><li><code>기사효율 100%</code>는 식에서 <code>1.0</code>이다. 기사는 일반 병력과 다른 단위이므로 총원과 무용을 같은 합으로 더하지 않는다.</li><li><code>N_i</code>는 전투 너비·생존 병력·배치를 반영한 개념적 수이며 소집 전체 병력과 같다고 가정하지 않는다.</li><li><code>k_adv</code>는 패치별 우위 피해 계수다. <code>0.02</code> 또는 <code>0.10</code> 중 하나를 현행값으로 확정하지 않는다.</li><li><code>k_day = 0.03</code>은 알려진 구판 일일 피해 환산 계수의 후보이지만 이번 원문 대조가 없다. 평균 강인함 산정, 피해 배분, 반올림, 사망자·도주자 분리까지 포함한 엔진 재현 공식이 아니다.</li><li>위 식의 <code>B_i</code> 단일 합은 설명용 축약이다. 실제 가산·곱산 보정 그룹과 적용 순서는 미확인이다.[S-CK3-M03; 원문 미확보]</li></ul><p><strong>[추론: 우위만 비교하는 예시]</strong> 다른 조건을 고정하고 유효 피해가 10,000, 우위 차가 10이면 <code>k_adv=0.02</code>일 때 12,000, <code>k_adv=0.10</code>일 때 20,000이다. 이는 버전 확인의 중요성을 보이는 계산이지 현재 CK3에서 어느 쪽이 실제 발생한다는 실행 결과가 아니다. 병력 수만으로 승패를 계산하는 공식도 아니다.</p><h3 id="_6-5-공성·보급·전쟁-점수-미확인" tabindex="-1">6.5 공성·보급·전쟁 점수 [미확인] <a class="header-anchor" href="#_6-5-공성·보급·전쟁-점수-미확인" aria-label="Permalink to &quot;6.5 공성·보급·전쟁 점수 [미확인]&quot;">​</a></h3><ul><li>적의 요새 영지를 포위하고 수비대보다 충분한 병력을 유지하면 공성이 진행된다. 공성 진행은 요새 수준·수비대·공성 병기·지휘 특성·공성 사건의 영향을 받는다.</li><li>공성 병기는 대응 가능한 최대 요새 수준이 있어 낡은 병기를 무한히 쌓는 것만으로 모든 성을 같은 속도로 함락할 수 없다.</li><li>성벽 돌파 후 강습이 가능해질 수 있으나 큰 병력 손실을 감수한다. 수도 함락은 군주·가족 포획 가능성 때문에 전략적 가치가 크다.</li><li>보급 한도보다 큰 병력을 한 지역에 집중하면 보급이 악화된다. 적지·질병·겨울·특정 이동 경로의 소모는 전투 없이 병력을 깎는다. 군대를 나눠 보급하다 교전 때 합치는 운용이 필요하다.</li><li>전쟁 점수는 전투, 목표 지역 점령·유지의 시간 누적, 기타 점령, 핵심 포로 등으로 구성된다. 일반적 강제 요구 기준은 <code>+100%</code>, 항복 측은 <code>-100%</code>이며 전투 점수 상한·목표 점수·특수 CB 예외가 있다.</li><li>적 군주 포획은 보통 결정적 전쟁 점수를 주지만, 동맹의 군주나 다른 전쟁의 포로를 잡았다고 현재 전쟁이 자동 종료되지는 않는다. 전쟁 점수 우세와 평화 협상 확정도 구별한다.[S-CK3-M03; 원문 미확보]</li></ul><h2 id="_7-지도-세계" tabindex="-1">7. 지도/세계 <a class="header-anchor" href="#_7-지도-세계" aria-label="Permalink to &quot;7. 지도/세계&quot;">​</a></h2><h3 id="_7-1-공간-계층과-관습권-미확인" tabindex="-1">7.1 공간 계층과 관습권 [미확인] <a class="header-anchor" href="#_7-1-공간-계층과-관습권-미확인" aria-label="Permalink to &quot;7.1 공간 계층과 관습권 [미확인]&quot;">​</a></h3><p>지도상의 작은 영지·남작령은 백작령, 공작령, 왕국, 제국 계층에 속한다. 군대 이동·공성의 공간과 세금·작위·상속의 공간은 서로 연결되지만 동일한 단위가 아니다. 백작령은 문화·신앙·개발도·통제 같은 상태를 가지며 내부 영지에는 성채·도시·사원 등의 유형이 있다.</p><p><strong>관습권 De jure</strong>은 법적으로 어느 상위 작위에 속하는가이고, <strong>실효 지배 De facto</strong>는 지금 실제로 누구의 봉신인가다. 다른 왕국의 관습권 공작령을 정복해도 즉시 관습권 지도가 바뀌지 않는다. 장기 통합은 관습권 이동 조건과 과업의 영향을 받는다. 주군보다 동급 이상인 작위를 수여하는 경우 독립 가능성을 검토해야 한다.</p><h3 id="_7-2-지도-모드는-같은-세계에-던지는-질문" tabindex="-1">7.2 지도 모드는 같은 세계에 던지는 질문 <a class="header-anchor" href="#_7-2-지도-모드는-같은-세계에-던지는-질문" aria-label="Permalink to &quot;7.2 지도 모드는 같은 세계에 던지는 질문&quot;">​</a></h3><p><strong>[문서]</strong> 정치 지도와 상세 지도는 선택 단위가 달라질 수 있고, 줌에 따라 양피지 표현과 상세 지형이 연결된다. 지도 호버는 영역·통치자·영지를 설명한다. 지도 모드는 별도 세계가 아니라 같은 장소의 정보 필터다.[S23][S30][S31][S-CK3-M01]</p><p><strong>[미확인]</strong> 정치·관습권·신앙·문화·개발도·통제·지형·보급 등의 정보는 서로 다른 판단에 사용한다. 강과 해협·상륙, 산악·숲·평야, 겨울, 보급 한도는 전쟁 경로를 바꾸고, 성지·특수 건물·지역 자원은 장기 정복 목표를 만든다. 정확한 메뉴 이름과 제공 모드는 버전에 따라 다르다.</p><h3 id="_7-3-문화의-구성-미확인" tabindex="-1">7.3 문화의 구성 [미확인] <a class="header-anchor" href="#_7-3-문화의-구성-미확인" aria-label="Permalink to &quot;7.3 문화의 구성 [미확인]&quot;">​</a></h3><p>문화는 단순한 민족별 고정 <code>+5%</code> 표가 아니다. <strong>기풍 Ethos</strong>, <strong>유산 Heritage</strong>, <strong>언어 Language</strong>, <strong>군사 관습</strong>, <strong>미학</strong>, <strong>전통 Traditions</strong>, <strong>혁신 Innovations</strong>이 결합한다. 문화와 신앙은 독립 상태여서 같은 문화의 다른 신앙, 같은 신앙의 다른 문화가 존재한다.</p><ul><li><strong>기풍</strong>은 전쟁·행정·정신·공동체 등 문화의 큰 경향을 부여한다.</li><li><strong>전통</strong>은 병종, 지형 전문화, 결혼·친족, 경제, 활동, 법·사회 관행 등의 구체 규칙을 바꾼다. 시대별 슬롯 한도·선행 조건·명예 비용·설립 시간이 있다.</li><li><strong>문화 수장</strong>은 보통 해당 문화 백작령을 가장 많이 지배하는 통치자이며 문화의 관심 혁신을 선택한다.</li><li><strong>혁신 연구</strong>는 문화 영지의 평균 개발도, 수장의 학습과 관심, 다른 문화로부터의 노출 등으로 진행된다. 관심 선택은 기술을 즉시 구입하는 것이 아니다.</li><li><strong>문화 수용도 Acceptance</strong>는 두 문화 사이의 공존 정도로, 통치·관계와 혼합 조건에 중요하다. 한 인물이 다른 문화를 좋아하는 개인 호감과 다른 값이다.[S-CK3-M05; 원문 미확보]</li></ul><h3 id="_7-4-문화-개혁·혼합·분화-미확인" tabindex="-1">7.4 문화 개혁·혼합·분화 [미확인] <a class="header-anchor" href="#_7-4-문화-개혁·혼합·분화-미확인" aria-label="Permalink to &quot;7.4 문화 개혁·혼합·분화 [미확인]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>수단</th><th>무엇을 바꾸는가</th><th>조건·비용·결과</th></tr></thead><tbody><tr><td>기존 문화 개혁</td><td>기존 문화의 전통 등을 조정</td><td>문화 수장 자격, 전통 조건, 명예, 설치 시간. 세계의 모든 문화원을 즉시 다른 문화로 바꾸는 행동이 아니다.</td></tr><tr><td>혼합 Hybridization</td><td>두 문화 요소를 선택해 새 혼합 문화를 구성</td><td>Royal Court 관련 기능. 영역 내 접촉·수용도·문화 조건, 명예 비용·재사용 제한이 있다. 알려진 기본 수용도 기준은 <code>40%</code>, 문화적 유연성 등으로 감소 가능하나 최신값 미확인. 두 부모 문화의 혁신을 결합하는 이점이 있다.</td></tr><tr><td>분화 Divergence</td><td>기존 문화에서 갈라진 새 문화를 구성</td><td>Royal Court 관련 기능. 명예 비용, 문화 변경 선택, 영역·기간 제약이 있다. 다른 부모 문화의 혁신을 자동으로 얻는 혼합과 다르다.</td></tr><tr><td>문화 촉진</td><td>백작령의 문화를 통치자 문화로 바꿈</td><td>관리관 시간과 장기 내정 기회비용. 사람 전체와 신앙까지 한 번에 전환하지 않는다.</td></tr></tbody></table><p>혼합·분화 때 새 문화가 차지할 지역과 전환하는 인물은 조건에 의해 정해진다. 군주가 새 문화를 만들었다고 모든 기존 영지가 즉시 전환하는 것은 아니다. 기본 재사용 대기 기간, 시대별 전통 슬롯, 모든 명예 가격은 이 조사에서 확인하지 못했다.[S-CK3-M05; 원문 미확보]</p><h2 id="_8-외교-세력" tabindex="-1">8. 외교/세력 <a class="header-anchor" href="#_8-외교-세력" aria-label="Permalink to &quot;8. 외교/세력&quot;">​</a></h2><h3 id="_8-1-의견-관계-공포-미확인" tabindex="-1">8.1 의견, 관계, 공포 [미확인] <a class="header-anchor" href="#_8-1-의견-관계-공포-미확인" aria-label="Permalink to &quot;8.1 의견, 관계, 공포 [미확인]&quot;">​</a></h3><p>의견은 일반적으로 <code>-100~+100</code> 범위이며 <strong>A가 B를 평가하는 값과 B가 A를 평가하는 값은 다르다</strong>. 방향성과 관계 범주의 존재는 선행 문서에서도 확인된다.[S20]</p><table tabindex="0"><thead><tr><th>원인</th><th>작동 방식</th><th>알려진 예·확인 경계</th></tr></thead><tbody><tr><td>일반 외교 기량</td><td>여러 인물의 기본 평가를 조정</td><td>정확한 기량당 값은 이번 대조 없음.</td></tr><tr><td>성격·덕목·죄악</td><td>같은·대립 성격과 신앙의 도덕 평가로 보정</td><td>동일 특성도 신앙 교리에 따라 평가가 달라질 수 있다.</td></tr><tr><td>단기·장기 재위</td><td>새 군주 불신과 장기 통치 신뢰</td><td>알려진 기본 단기 재위 최대 불이익 <code>-20</code>은 정부·보정·패치 예외 미확인.</td></tr><tr><td>유력 봉신의 자리 요구</td><td>자문회에서 배제된 주요 봉신 불만</td><td>알려진 기본 <code>-40</code>; 모든 봉신에게 적용되는 값이 아니다.</td></tr><tr><td>작위 욕구·계층 불일치</td><td>관습권 봉신·작위를 원하는 인물이 불만</td><td>어떤 작위·누구에 대한 보정인지 개별로 확인.</td></tr><tr><td>선물·설득·친교·작위 수여</td><td>특정 방향의 의견을 올림</td><td>선물은 금, 설득은 계책 슬롯·시간, 수여는 소유권을 소비한다.</td></tr><tr><td>폭정 Tyranny</td><td>정당하지 않은 투옥·박탈·처형 등으로 집단적 불만</td><td>피해자 개인의 원한과 별도의 누적 불이익. 불법 행위마다 동일 수치가 아니다.</td></tr><tr><td>공포 Dread</td><td>상대의 담력에 따라 위축·공포 상태를 유도</td><td>대표 범위 <code>0–100</code>. 좋아하게 만드는 것이 아니라 저항을 억제하는 별도 축이다.</td></tr><tr><td>전임자 의견</td><td>이전 군주와의 관계가 새 군주 평가에 일부 반영</td><td>기존 호감 전체가 그대로 상속되는 것은 아니다.</td></tr></tbody></table><p><strong>[추론]</strong> 의견 <code>+100</code>만으로 동맹·봉신화·모든 계책 협조를 보장할 수 없다. 제안에는 작위 등급, 거리, 종교, 군사력, 친족 관계, 계약, 성격 같은 별도 조건이 있다. 공포로 유지한 복종은 공포가 낮은 후계자에게 취약할 수 있다.</p><h3 id="_8-2-봉신-왕권-파벌-미확인" tabindex="-1">8.2 봉신, 왕권, 파벌 [미확인] <a class="header-anchor" href="#_8-2-봉신-왕권-파벌-미확인" aria-label="Permalink to &quot;8.2 봉신, 왕권, 파벌 [미확인]&quot;">​</a></h3><p>주군은 봉신을 통해 큰 영역을 간접 통치한다. 직할 한도와 봉신 수 한도는 별개다. 공작 아래 백작을 정리하면 직접 봉신 수를 줄일 수 있지만 중간 주군이 더 강해지고 세금·병력은 간접 전달된다. 왕권은 작위 박탈·봉신 간 전쟁·계승 통제 등 권한을 넓히는 대신 봉신 의견과 정치적 저항을 유발한다.</p><p>대표 파벌은 <strong>자유 Liberty</strong>(왕권 하향), <strong>독립 Independence</strong>, <strong>주장자 Claimant</strong>(다른 인물 옹립), <strong>해체 Dissolution</strong>(상위 영역 해체), 민중·농민의 종교·문화·민심 불만이다. 파벌의 군사력 비율과 불만이 조건에 도달하면 최후통첩을 보내고 거절 시 내전이 될 수 있다. 군주와의 동맹, 투옥, 친교·강한 구실·공포 등은 파벌 참여를 막거나 억제할 수 있으나 적용 조건과 예외는 서로 다르다. 모든 파벌을 동일한 80% 또는 동일한 의견 임계값 하나로 설명하지 않는다.</p><h3 id="_8-3-혼인-동맹과-구실·계책" tabindex="-1">8.3 혼인 동맹과 구실·계책 <a class="header-anchor" href="#_8-3-혼인-동맹과-구실·계책" aria-label="Permalink to &quot;8.3 혼인 동맹과 구실·계책&quot;">​</a></h3><p><strong>[문서]</strong> 비밀·구실·계책은 인물에게 영향력을 행사하는 연결 체계다. 계책은 대상·요구조건·성공 효과를 가지며 성공과 발각은 구별되는 변수다.[S28][S30][S33]</p><p>세부 운용은 **[미확인]**이다.</p><ul><li><strong>혼인·약혼 동맹</strong>: 친족 결혼을 통해 군사 동맹을 만든다. 소집 시 명예 비용·참전 거절의 불이익, 다른 전쟁과의 이해 충돌이 있다. 친족 관계 종료·사망으로 유지 조건이 달라질 수 있다.</li><li><strong>약한 구실</strong>: 특정 거래에서 한 번 쓰는 영향력으로 이해할 수 있다. 의무 변경·혼인·복종 요구 등에서 수락을 보정하되 모든 금지 조건을 무시하지 않는다.</li><li><strong>강한 구실</strong>: 지속되는 강한 강제력이며 사용 간 대기·대상 행동 제한이 있다. 비밀을 폭로하면 그 비밀을 협박 수단으로 계속 쓸 수 없게 될 수 있다.</li><li><strong>개인 계책</strong>: 설득·친교·유혹·로맨스·언어 학습 등. 좋은 관계나 특정 특전을 목표로 한다.</li><li><strong>적대 계책</strong>: 살해·납치·구실 조작 등. 계책 능력, 방어, 내부 협력자, 접근성·단계에 따라 진행한다.</li><li><strong>비용</strong>: 착수 금이 항상 고정으로 드는 것은 아니다. 협력자 매수, 명예·신앙, 계책 슬롯·진행 시간, 스트레스, 발각 시 범죄·원한·전쟁 위험을 함께 본다.</li><li><strong>버전 경계</strong>: 과거의 월별 진척·성공률·비밀도 중심 설명과 후속의 단계·요원 역할·우위 자원 중심 체계를 합쳐 가짜 공식을 만들지 않는다. &#39;언제나 성공률 상한 95%&#39; 같은 구판 상수를 현행 전체 계책에 적용하지 않는다.</li></ul><h3 id="_8-4-명분-claims와-전쟁-명분-casus-belli-미확인" tabindex="-1">8.4 명분 Claims와 전쟁 명분 Casus Belli [미확인] <a class="header-anchor" href="#_8-4-명분-claims와-전쟁-명분-casus-belli-미확인" aria-label="Permalink to &quot;8.4 명분 Claims와 전쟁 명분 Casus Belli [미확인]&quot;">​</a></h3><p><strong>작위에 대한 권리 주장 Claim</strong>과 <strong>그 주장을 사용한 전쟁 사유 CB</strong>는 다르다. 명분을 갖고 있어도 선전포고 자격·성별·신앙·휴전·봉신 권한 등의 제한을 받는다.[S-CK3-M02][S-CK3-M03; 원문 미확보]</p><table tabindex="0"><thead><tr><th>유형</th><th>취득·사용</th><th>승리 결과·대가</th></tr></thead><tbody><tr><td>개인 작위 명분</td><td>계승·가족 권리, 사제의 위조, 종교 수장 요청, 특전 등</td><td>지정 작위를 얻는다. 위조 완료 금, 요청 신앙, 전쟁 명예 등 취득·사용 비용이 별개다.</td></tr><tr><td>압박된·미압박된 명분</td><td>압박된 명분은 다음 세대에 약화된 형태로 이어질 수 있고 미압박 명분은 보통 자동 영속하지 않는다.</td><td>패배하지 않고 명분 전쟁을 수행하는 조건 등이 권리 상태에 영향을 줄 수 있다. 정확한 상속 자격·평화 결과별 변화는 UI 확인 필요.</td></tr><tr><td>다른 인물의 명분</td><td>궁정 인물·봉신·친족의 권리를 대신 주장</td><td>수혜자가 작위를 받는다. 수혜 작위가 공격자보다 낮은지 등 조건에 따라 봉신으로 편입되거나 독립한다.</td></tr><tr><td>관습권 전쟁</td><td>자신의 작위에 법적으로 속한 지역을 요구</td><td>해당 영토·봉신 관계를 정리한다. 기술에 따라 한 번에 요구할 범위가 달라질 수 있다.</td></tr><tr><td>정복 Conquest</td><td>부족·특정 신앙·문화·정부 등의 자격</td><td>백작령·공작령 등을 정복한다. 위신·헌신 등급과 자원 비용·대상 제약이 있다.</td></tr><tr><td>성전 Holy War</td><td>적대적 신앙과의 종교 전쟁</td><td>백작령·공작령·왕국 규모가 가능하고 신앙 비용·헌신 요구가 있다. 상대 신앙 통치자들이 방어에 가담할 수 있다.</td></tr><tr><td>침공·복속</td><td>특정 정부·종교·문화·결단·인물 자격</td><td>넓은 영토나 통치자를 굴복시킨다. 평생 횟수 제한 등 CB별 제약을 가진다.</td></tr><tr><td>대성전 Great Holy War</td><td>종교 수장·교리·시기 등의 조건</td><td>여러 참여자가 기여하고 수혜자에게 작위를 분배하는 별도 체계. 일반 성전과 같지 않다.</td></tr><tr><td>파벌·폭정 전쟁</td><td>최후통첩 거절·부당한 통치 조치</td><td>왕권 변경·독립·군주 교체·해체 등 정치적 결과가 목표다.</td></tr></tbody></table><p>휴전 파기는 명예·외교 불이익을 만들 수 있고, 같은 땅을 점령해도 전쟁의 법적 목표 밖이면 마음대로 합병하지 못한다. 공격 승리·무승부·항복의 배상·권리 변화는 CB마다 다르므로 선전포고 화면의 세 결과를 별도로 읽어야 한다.</p><h2 id="_9-이벤트-내러티브" tabindex="-1">9. 이벤트/내러티브 <a class="header-anchor" href="#_9-이벤트-내러티브" aria-label="Permalink to &quot;9. 이벤트/내러티브&quot;">​</a></h2><h3 id="_9-1-사건이-인물의-상태를-바꾸는-방법" tabindex="-1">9.1 사건이 인물의 상태를 바꾸는 방법 <a class="header-anchor" href="#_9-1-사건이-인물의-상태를-바꾸는-방법" aria-label="Permalink to &quot;9.1 사건이 인물의 상태를 바꾸는 방법&quot;">​</a></h3><p><strong>[문서]</strong> 이벤트는 관련 초상·상황·선택을 결합하고 조건부 또는 비활성 선택, 숨은 효과를 지원한다. 선택 개수는 고정 2–4개가 아니다. 선택 툴팁의 미래 효과와 이미 발생한 결과를 구별해야 한다. 생활방식은 수치 보너스뿐 아니라 인물의 이야기를 만든다는 설계 의도가 선행 문서에 기록되어 있다.[S25][S31][S32]</p><p><strong>[미확인]</strong> 사건의 유발 조건은 활동·생활방식·가족·특성·궁정·여행·전쟁·종교·문화·이전 사건 플래그 등이다. 선택은 자원·스트레스·의견·관계·건강·특성·명분·비밀·후속 사건을 바꿀 수 있다. 학습이나 성격으로 열리는 특별 선택도 있지만 모든 능력 판정이 같은 선형 성공률 공식을 사용하지는 않는다.</p><p><strong>[추론]</strong> 내러티브는 완전히 별도의 스토리 캠페인이 아니라 시스템 상태의 재해석이다. &#39;자비로운 군주가 반란 지도자를 처형할 것인가&#39;는 금·안전·공포·성격 비용이 동시에 걸린 의사결정이며, 승리 보상과 개인적 손실을 같은 선택에 둔다.</p><h3 id="_9-2-종교·신앙·교리-미확인" tabindex="-1">9.2 종교·신앙·교리 [미확인] <a class="header-anchor" href="#_9-2-종교·신앙·교리-미확인" aria-label="Permalink to &quot;9.2 종교·신앙·교리 [미확인]&quot;">​</a></h3><p>종교 가족, 종교, 개별 신앙 Faith를 구별한다. 실제 플레이의 혼인·범죄·성직·종교 적대 규칙은 개별 신앙의 교리와 핵심 교리에 의해 결정된다. 가톨릭과 정교회처럼 같은 종교 안에서도 다른 신앙이면 종교 수장·성지·교리와 상호 평가가 다를 수 있다.[S-CK3-M04; 원문 미확보]</p><ul><li><strong>핵심 교리 Tenets</strong>: 보통 세 개의 큰 규칙 묶음. 무장 순례·공동체 정체성·식인 의식·자연 원시주의 등은 전쟁·활동·덕목·사회 관행을 바꾼다. 실제 선택 가능성은 종교·상호 배타 조건에 달린다.</li><li><strong>주요 교리 Doctrines</strong>: 성별 역할, 종교적 태도, 종교 수장, 결혼·이혼·서자·근친, 동성 관계·간통·일탈·마법의 범죄 여부, 성직 임명·혼인·성별 등.</li><li><strong>덕목·죄악</strong>: 성격의 종교적 평가를 바꾸어 신앙·성직자 의견·사건 선택에 영향을 준다. 특정 특성이 모든 신앙에서 죄악인 것은 아니다.</li><li><strong>성지 Holy Sites</strong>: 신앙마다 중요 장소가 있으며 통제·신앙 조건에 따라 신도 보너스나 개혁 자격에 영향을 준다.</li><li><strong>열성 Fervor</strong>: 신앙 전체의 종교적 활력으로 개인 신앙 잔고와 다르다. 개종·이단·창설 비용 등의 압력에 관여한다.</li><li><strong>신앙 간 적대</strong>: 의롭다·그릇되었다·적대적·사악하다 등 관계는 종교 가족·태도·특수 교리로 결정된다. &#39;다른 신앙이면 모두 성전 가능&#39;이 아니다.</li></ul><h3 id="_9-3-사용자-신앙-창설과-비개혁-신앙-개혁-미확인" tabindex="-1">9.3 사용자 신앙 창설과 비개혁 신앙 개혁 [미확인] <a class="header-anchor" href="#_9-3-사용자-신앙-창설과-비개혁-신앙-개혁-미확인" aria-label="Permalink to &quot;9.3 사용자 신앙 창설과 비개혁 신앙 개혁 [미확인]&quot;">​</a></h3><p><strong>새 신앙 창설</strong>은 현재 종교에서 갈라져 핵심 교리·세부 교리·이름 등을 정하고 큰 신앙 비용을 내는 행동이다. 선택한 교리와 기존 신앙의 차이·열성·특전 등이 가격을 바꾸므로 고정 &#39;신앙 5,000&#39; 규칙으로 설명할 수 없다. 선지자 특전의 비용 절감은 §5.2의 미검증 기본 효과다.</p><p><strong>비개혁 신앙 개혁</strong>은 조직되지 않은 신앙을 조직화하는 별도 경로이며, 알려진 기본 조건에는 해당 신앙 성지 <code>3곳</code> 통제가 있다. 이미 조직된 신앙에서 새 신앙을 만드는 모든 경우에 이 성지 조건을 붙여서는 안 된다.</p><p>창설·개혁은 군주의 개인 개종만으로 끝나지 않는다. 가족·봉신의 동참 여부, 영지 개종 시간, 기존 종교와의 적대·성전, 성직 수입과 혼인 적법성 변화가 뒤따른다. 성직자를 세속 군주의 통제 아래 두는 교리와 독립 종교 수장을 두는 교리는 정치경제 구조까지 다르게 만든다. 정확한 비용 계산식·성지 조건의 예외·생애별 제한은 원문 확인 전 확정하지 않는다.[S-CK3-M04; 원문 미확보]</p><h3 id="_9-4-이베리아-투쟁-iberian-struggle-미확인" tabindex="-1">9.4 이베리아 투쟁 Iberian Struggle [미확인] <a class="header-anchor" href="#_9-4-이베리아-투쟁-iberian-struggle-미확인" aria-label="Permalink to &quot;9.4 이베리아 투쟁 Iberian Struggle [미확인]&quot;">​</a></h3><p>Fate of Iberia의 고유 지역 체계다. 정복 횟수만 세는 임무가 아니라 <strong>지역 인물들의 행동이 단계 전환을 밀고, 단계가 다시 가능한 행동과 비용을 바꾸는 피드백 구조</strong>다. 이 항목의 전용 위키는 조사 상한 때문에 요청하지 않았으므로 아래 상세는 모두 미확인이다.</p><p><strong>참여 지위</strong>는 이베리아 투쟁 지역, 수도·통치 위치, 관련 문화·신앙 등의 조건으로 판정된다. 관여자 Involved, 외부에서 접한 침입자 Interloper 등은 같은 땅에 있어도 적용되는 규칙이 다를 수 있다. 단지 스페인계 이름을 가졌다고 관여자가 되는 것은 아니다.</p><table tabindex="0"><thead><tr><th>단계</th><th>의미·대표 경향</th><th>다음 단계에 대한 이해</th></tr></thead><tbody><tr><td>기회 Opportunity</td><td>정복과 협력 양쪽이 열려 있는 재편기</td><td>행동 촉매에 따라 적대 또는 타협 방향으로 이동한다.</td></tr><tr><td>적대 Hostility</td><td>종교·정치적 경쟁과 공격의 비중이 커짐</td><td>영구 전쟁 상태가 아니라 이후 긴장 완화와 다음 순환으로 이어질 수 있다.</td></tr><tr><td>타협 Compromise</td><td>실용적 협력과 공존의 비중이 커짐</td><td>이후 회유 방향으로 이어지는 순환의 일부다.</td></tr><tr><td>회유 Conciliation</td><td>관계 형성·공존에 유리한 국면</td><td>이후 다시 기회 단계로 돌아갈 수 있다.</td></tr></tbody></table><p><strong>촉매 Catalysts</strong>는 전쟁·동맹·혼인·문화 수용·구실 사용·관계와 각종 지역 행동에 붙은 단계 진행 기여다. 현재 단계에 활성화된 촉매만 해당 방향 점수에 기여하므로 아무 선물이나 모든 단계에서 똑같이 전환을 가속하지 않는다. 정확한 촉매 목록·점수·전환 임계값과 단계별 비용 보정은 이 조사에서 확인하지 못했다.</p><p><strong>대표 종결 경로</strong>는 다음과 같다.</p><ul><li><strong>지배 Dominance</strong>: 군사·영토·문화·신앙의 우위를 통해 투쟁을 끝낸다. 특정 적대 국면과 지역 통합 조건을 요구하는 경로로 알려져 있다.</li><li><strong>현상 유지 Status Quo / Detente</strong>: 분할된 세력권을 제도화한다. 하나의 황제가 전부 합병하는 결말과 다르다.</li><li><strong>화해 Conciliation / Rapprochement</strong>: 다른 신앙·문화 세력과 안정적 공존을 형성한다. 외교 관계와 해당 국면의 조건이 중요하다.</li></ul><p>종결 결단은 단계만 맞추면 되는 버튼이 아니다. 이베리아 영토 비율, 독립 통치자 관계, 수도·왕국의 문화·신앙 통합 같은 구체 자격을 요구하며 패치에 따라 변경되어 왔다. 종결 이후 작위 구조·지역 보정이 달라질 수 있다. 여기서 최신 영토 비율·정확한 결단 ID·보너스 수치를 창작하지 않는다.</p><p><strong>[추론]</strong> 투쟁의 특징은 &#39;최선의 군사 행동&#39;과 &#39;원하는 결말의 촉매&#39;가 충돌할 수 있다는 점이다. 화해 결말을 원하면서 적대 촉매만 계속 만들면 개인의 확장이 지역 시스템의 목표를 방해할 수 있다.</p><h2 id="_10-난이도-압박" tabindex="-1">10. 난이도/압박 <a class="header-anchor" href="#_10-난이도-압박" aria-label="Permalink to &quot;10. 난이도/압박&quot;">​</a></h2><h3 id="_10-1-스트레스-성격에-역행하는-선택의-비용" tabindex="-1">10.1 스트레스: 성격에 역행하는 선택의 비용 <a class="header-anchor" href="#_10-1-스트레스-성격에-역행하는-선택의-비용" aria-label="Permalink to &quot;10.1 스트레스: 성격에 역행하는 선택의 비용&quot;">​</a></h3><p><strong>[문서]</strong> 성격과 어긋나는 선택에 스트레스 비용을 붙여 역할극과 효율적 의사결정의 충돌을 만든다. 스트레스가 화면에 존재한다는 사실과 플레이어가 쉽게 발견한다는 사실은 다르며, 출시 리뷰는 좌하단 표시를 처음 놓쳤다가 정정했다.[S29][S30][S31][S-CK3-M01]</p><p>아래 수치와 트리거·대처는 **[미확인]**이다.</p><table tabindex="0"><thead><tr><th>스트레스</th><th>단계</th><th>대표 압박</th></tr></thead><tbody><tr><td><code>0–99</code></td><td>0</td><td>기본 스트레스 구간. 특정 스트레스 활용 특전은 별도다.</td></tr><tr><td><code>100–199</code></td><td>1</td><td>첫 높은 스트레스 단계, 정신 붕괴 위험·관련 불이익.</td></tr><tr><td><code>200–299</code></td><td>2</td><td>생식력·건강 등의 부담과 더 무거운 붕괴 선택.</td></tr><tr><td><code>300 이상</code></td><td>3</td><td>가장 위험한 붕괴와 건강·통치 위기. 최대 저장 범위·강제 감소 처리의 최신 규칙은 미확인.</td></tr></tbody></table><p>정신 붕괴 Mental Break는 높은 스트레스 진입과 재발 조건에 따라 사건으로 나타난다. 단계가 높을수록 선택지가 더 파괴적일 수 있으며, 모든 100점 도달마다 쿨다운과 무관하게 동일 사건이 즉시 반복되는 단순 게이지가 아니다. 알려진 붕괴 재발 대기와 단계별 생식력·건강의 정확한 값은 이번 조사에서 대조하지 못했다.</p><h3 id="_10-2-구체적인-스트레스-트리거와-대처-미확인" tabindex="-1">10.2 구체적인 스트레스 트리거와 대처 [미확인] <a class="header-anchor" href="#_10-2-구체적인-스트레스-트리거와-대처-미확인" aria-label="Permalink to &quot;10.2 구체적인 스트레스 트리거와 대처 [미확인]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>인물·상황</th><th>스트레스가 생기는 대표 행동·사건</th><th>반대 선택의 대가</th></tr></thead><tbody><tr><td>자비로움 Compassionate</td><td>처형·고문·잔혹한 행동 등</td><td>살려 보내면 반란자·경쟁자가 다시 행동할 수 있다.</td></tr><tr><td>정직함 Honest·공정함 Just</td><td>거짓말·부정한 계책·불의한 처벌 관련 선택</td><td>진실 공개가 외교·가족 관계를 파괴할 수 있다. 정확한 비용은 선택별로 다르다.</td></tr><tr><td>탐욕 Greedy</td><td>금을 나눠 주는 선물·기부·특정 관대한 선택</td><td>금을 지키면 봉신 달래기·필요한 사건 해결을 놓칠 수 있다.</td></tr><tr><td>수줍음 Shy</td><td>낯선 사람과의 교류·초대·대규모 사교의 특정 선택</td><td>사교 기피가 동맹·인재·관계 형성을 방해한다.</td></tr><tr><td>야심 Ambitious</td><td>지위를 포기하거나 특정 조건에서 작위를 수여하는 선택</td><td>직접 보유 집착이 직할 초과·봉신 불만을 낳는다. 모든 작위 수여가 무조건 같은 스트레스는 아니다.</td></tr><tr><td>친구·가족 사망</td><td>가까운 관계의 죽음·비극</td><td>관계망이 풍부한 군주도 연속 사별에 취약하다.</td></tr><tr><td>고문·구금·사건 실패</td><td>피해 상태나 특정 사건 효과</td><td>직접 통제할 수 없는 외부 사건도 스트레스를 만든다.</td></tr></tbody></table><ul><li><strong>대처 특성 Coping mechanisms</strong>: 음주, 대마 사용, 은둔, 난폭한 감정 표출, 식욕 상실, 폭식, 방탕, 무절제한 소비, 자해 같은 부정적·양면적 대처와 운동, 일기 쓰기, 친구에게 털어놓기 같은 상대적으로 건전한 대처가 있다. 이용 가능성은 사건·특성·신앙·관계에 달린다.</li><li><strong>대처 결정</strong>: 스트레스를 낮추는 대신 금·건강·기량·의견·관계·행동 대기 시간을 지불할 수 있다. 운동도 부상 위험이 전혀 없는 무조건 무료 회복으로 단정하지 않는다.</li><li><strong>사냥·연회·순례·여행</strong>: 활동과 이벤트에서 스트레스가 변하지만 모든 성격이 같은 활동으로 항상 회복하지 않는다. 수줍은 인물에게 사교 선택이 오히려 부담일 수 있다.</li><li><strong>붕괴 선택</strong>: 새 대처 특성을 받고 당장 완화하거나, 이를 거부하고 더 높은 스트레스를 감수하거나, 더 심각한 자기 파괴·정치적 결과로 이어질 수 있다. 단계별 모든 이벤트가 퇴위·자살 같은 같은 선택을 보장하지 않는다.</li></ul><p><strong>[추론]</strong> 스트레스의 설계적 역할은 선택을 금으로 환산하지 못하게 만드는 것이다. 같은 반란자 처분이라도 가학적 군주와 자비로운 군주에게 최적 선택이 달라진다. 스트레스 감소만 최적화하면 재정·도덕·인재·건강이 악화될 수 있다.</p><h3 id="_10-3-복합-위기와-난이도-조절-미확인" tabindex="-1">10.3 복합 위기와 난이도 조절 [미확인] <a class="header-anchor" href="#_10-3-복합-위기와-난이도-조절-미확인" aria-label="Permalink to &quot;10.3 복합 위기와 난이도 조절 [미확인]&quot;">​</a></h3><ul><li><strong>계승 위기</strong>: 강한 장기 재위 군주가 죽으면 분할·단기 재위·새로운 관계·미성년·약한 군대가 동시에 겹친다.</li><li><strong>확장 과부하</strong>: 낮은 통제력, 다른 신앙·문화, 직할·봉신 한도, 강한 신규 봉신, 장거리 방어가 정복의 수익을 지연시킨다.</li><li><strong>군사·재정 악순환</strong>: 장기 소집 → 부채 → 약화된 전쟁 수행 → 포로·배상 → 재건 지연의 연쇄가 가능하다.</li><li><strong>건강·역병·여행</strong>: 나이·질병·부상·치료·활동 위험은 계획한 사망 순서와 교육·혼인 계획을 깨뜨린다. 역병·여행 세부는 관련 패치·DLC 범위를 구별한다.</li><li><strong>외부 압력</strong>: 강대국, 대성전, 침공, 이웃 동맹망, 유산 명분이 성장한 영역을 공격할 수 있다.</li><li><strong>설정·시작 조건</strong>: 난이도, 역사 시작 인물, 영역 크기·위치, 신앙·문화, 계승법, 질병·몽골·일탈 등 게임 규칙이 실제 압력을 바꾼다. Ironman은 저장·되돌리기 제약이지 자체적으로 적 군대에 고정 보너스를 주는 동일 개념이 아니다. 도전과제와 Ironman의 연동 조건은 출시 후 바뀌었으므로 현행 요구를 단정하지 않는다.</li></ul><h3 id="_10-4-시스템을-읽는-최종-점검표-추론" tabindex="-1">10.4 시스템을 읽는 최종 점검표 [추론] <a class="header-anchor" href="#_10-4-시스템을-읽는-최종-점검표-추론" aria-label="Permalink to &quot;10.4 시스템을 읽는 최종 점검표 [추론]&quot;">​</a></h3><ol><li>이 자원과 보정은 인물·영지·왕조 중 누구의 것인가?</li><li>이번 선택은 즉시 금만 쓰는가, 과업·계책·활동 시간도 점유하는가?</li><li>사망하면 작위·부대·관계·유산 중 무엇이 누구에게 남는가?</li><li>군사력 표시는 보급·지형·상성·기사·우위를 반영하지 않은 단순 총원인가?</li><li>전쟁 승리 시 작위를 받는 사람은 나인가, 명분 보유자인가? 그가 내 봉신으로 남는가?</li><li>문화·신앙 변경은 인물만 바꾸는가, 영지·봉신·전쟁 적대까지 바꾸는가?</li><li>지금의 정치적 효율이 내 성격의 스트레스와 다음 세대의 반란 비용을 높이는가?</li><li>이베리아에서 해당 행동은 개인 목표와 어떤 단계 촉매를 동시에 움직이는가?</li></ol><h3 id="_10-5-출처-확인-범위와-남은-검증" tabindex="-1">10.5 출처, 확인 범위와 남은 검증 <a class="header-anchor" href="#_10-5-출처-확인-범위와-남은-검증" aria-label="Permalink to &quot;10.5 출처, 확인 범위와 남은 검증&quot;">​</a></h3><table tabindex="0"><thead><tr><th>S-ID</th><th>자료</th><th>이 문서에서의 상태·용도</th></tr></thead><tbody><tr><td>S-CK3-M01</td><td><a href="https://github.com/islee23520/seoul-kenshi/blob/docs/reference-context-sync-st_01a079f1/.omo/research/ck3-ui-reference.md" target="_blank" rel="noreferrer">로컬 CK3 UI 레퍼런스</a></td><td><strong>직접 읽음.</strong> 18개 원출처 기록과 공개 화면 관찰을 계승. 인물 중심성, 다섯 기량·건강의 구별, 자문회, 계책의 성공/발각, 의견 방향, 지도, 스트레스, 이벤트 정보 공개 범위의 근거.</td></tr><tr><td>S19·S20·S21</td><td><a href="https://ck3.paradoxwikis.com/Beginner%27s_guide" target="_blank" rel="noreferrer">Beginner&#39;s guide</a>, <a href="https://ck3.paradoxwikis.com/Character" target="_blank" rel="noreferrer">Character</a>, <a href="https://ck3.paradoxwikis.com/Attributes" target="_blank" rel="noreferrer">Attributes</a></td><td><strong>선행 문서 경유.</strong> 이번 원문 재조회 없음. 상세 수치 확인으로 확장하지 않음.</td></tr><tr><td>S23·S27·S28</td><td>지도 개발일지 공식 공지, <a href="https://ck3.paradoxwikis.com/Council" target="_blank" rel="noreferrer">Council</a>, <a href="https://ck3.paradoxwikis.com/Schemes" target="_blank" rel="noreferrer">Schemes</a></td><td><strong>선행 문서 경유.</strong> 지도 기능 주제, 기량-과업 연결, 계책 구조. 최신 과업·계책 수치 근거 아님.</td></tr><tr><td>S25</td><td><a href="https://ck3.paradoxwikis.com/Event_modding" target="_blank" rel="noreferrer">Event modding</a></td><td><strong>선행 문서 경유.</strong> 옵션 수 비고정, 조건부·숨은 효과, AI 선택 가중치의 의미.</td></tr><tr><td>S29·S30·S31</td><td><a href="https://www.pcgamer.com/crusader-kings-3-review/" target="_blank" rel="noreferrer">PC Gamer</a>, <a href="https://www.ign.com/articles/crusader-kings-3-review" target="_blank" rel="noreferrer">IGN</a>, <a href="https://www.rockpapershotgun.com/crusader-kings-3-review" target="_blank" rel="noreferrer">RPS</a></td><td><strong>선행 문서 경유.</strong> 인물·스트레스·중첩 툴팁·출시 화면·간접 전투. 현재 버전 실증 아님.</td></tr><tr><td>S32·S33</td><td>생활방식, 비밀·구실·계책의 공식 Steam 개발일지 공지</td><td><strong>선행 문서 경유.</strong> 공지에서 확인된 설계 주제만 사용. 포럼 전문 확인 아님.</td></tr><tr><td>S-CK3-M02</td><td><a href="https://ck3.paradoxwikis.com/api.php?action=parse&amp;page=Succession&amp;prop=wikitext&amp;format=json" target="_blank" rel="noreferrer">Succession API</a></td><td><strong>요청 실패 기록.</strong> HTTP 응답이 HTML 검증 페이지라 JSON 파싱 불가. 계승 배분·법별 의견 수치의 증거 없음.</td></tr><tr><td>S-CK3-M03</td><td><a href="https://ck3.paradoxwikis.com/api.php?action=parse&amp;page=Warfare&amp;prop=wikitext&amp;format=json" target="_blank" rel="noreferrer">Warfare API</a></td><td><strong>요청 실패 기록.</strong> 전투 계수·상성·공성·CB 세부의 증거 없음.</td></tr><tr><td>S-CK3-M04</td><td><a href="https://ck3.paradoxwikis.com/api.php?action=parse&amp;page=Religion&amp;prop=wikitext&amp;format=json" target="_blank" rel="noreferrer">Religion API</a></td><td><strong>요청 실패 기록.</strong> 신앙 창설·개혁·교리 수치의 증거 없음. 상위 페이지가 모든 하위 규칙을 포함한다고 가정하지 않음.</td></tr><tr><td>S-CK3-M05</td><td><a href="https://ck3.paradoxwikis.com/api.php?action=parse&amp;page=Culture&amp;prop=wikitext&amp;format=json" target="_blank" rel="noreferrer">Culture API</a></td><td><strong>요청 실패 기록.</strong> 문화·전통·혼합·분화·혁신 수치의 증거 없음.</td></tr><tr><td>S-CK3-M06</td><td><a href="https://ck3.paradoxwikis.com/api.php?action=parse&amp;page=Dynasties&amp;prop=wikitext&amp;format=json" target="_blank" rel="noreferrer">Dynasties API</a></td><td><strong>요청 실패 기록.</strong> 왕조 명성·유산 25단계의 정확한 현행 효과를 입증하지 못함.</td></tr></tbody></table><p>원문 응답과 조회 상태는 <code>.omo/evidence/gameplay-rubric-6d3fe97/ui-reference/ck3-mechanics-raw/</code>에 보관한다. <code>.json</code> 확장자의 다섯 원응답 파일은 <strong>유효 JSON이 아니라 반환된 HTML</strong>이며, <code>fetch-status.json</code>만 구조화된 조회 기록이다. 출처 레지스트리는 같은 상위 디렉터리의 <code>sources.json</code>에 추가했다.</p><p><strong>검증 결론:</strong> 요청된 열 개 시스템 영역과 구체 사례·비용·상호작용은 모두 서술했지만, 신뢰 수준은 균일하지 않다. 현재 패치의 계승법 의견 표, 전투 엔진 수식, 25개 유산의 완전 효과, 계책 개편 수치, 씨족 세금 공식, 문화 가격·기간, 신앙 비용식, 이베리아 촉매·종결 조건은 <strong>미확인</strong>이다. 이 문서는 구조와 검증 경계를 갖춘 한국어 메커니즘 참고서이며, 전 항목이 현행 원문으로 검증된 위키의 대체물이라는 주장은 하지 않는다.</p>`,150)])])}const u=r(o,[["render",i]]);export{p as __pageData,u as default};
